function drawTree(x,y,s){circle(x+.12*s,y+.55*s,.48*s,'#7c9c5d');circle(x-.23*s,y+.34*s,.4*s,'#88a964');circle(x+.42*s,y+.28*s,.38*s,'#9ab86d');circle(x+.06*s,y+.12*s,.42*s,'#91b16a');rect(x-.06*s,y+.45*s,.13*s,.5*s,'#826046');circle(x-.1*s,y+.3*s,.05*s,'#b7ca7b');}

const hud = {
  day: document.getElementById('dayLabel'),
  clock: document.getElementById('clock'),
  toast: document.getElementById('toast'),
  hint: document.getElementById('hint'),
  objective: document.getElementById('objective'),
  goalProgress: document.getElementById('goalProgress'),
  goalCount: document.getElementById('goalCount'),
  seedCount: document.getElementById('seedCount'),
  goldCount: document.getElementById('goldCount'),
  dayOverlay: document.getElementById('dayOverlay'),
  daySummary: document.getElementById('daySummary'),
  nextDay: document.getElementById('nextDay'),
  soundBtn: document.getElementById('soundBtn')
};

const objectiveStages = [
  { title: 'Plant 4 parsnip seeds', desc: 'Walk to a tilled patch and press E to plant.', target: 4, type: 'plant' },
  { title: 'Water the sprouts', desc: 'Use your watering can on the planted plots.', target: 4, type: 'water' },
  { title: 'Harvest 4 crops', desc: 'Gather the fully grown parsnips for money.', target: 4, type: 'harvest' },
  { title: 'Earn 80g total', desc: 'Sell the harvest at the market next to the house.', target: 80, type: 'money' }
];

const state = {
  day: 1,
  minute: 360,
  totalSeeds: 8,
  gold: 120,
  planted: 0,
  harvested: 0,
  moneyEarned: 0,
  objectiveIndex: 0,
  toastTimer: 0,
  overlayVisible: false,
  gameTime: 0,
  soundOn: true
};

const actionButtons = document.querySelectorAll('[data-action]');

function getDayName(day) {
  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  return days[(day - 1) % 7];
}

function formatDay() {
  const suffix = ['th', 'st', 'nd', 'rd'];
  const n = state.day % 10;
  const suffixText = suffix[(state.day % 100 > 10 && state.day % 100 < 20) ? 0 : (n < 4 ? n : 0)];
  return `${getDayName(state.day)}, ${state.day}${suffixText}`;
}

function formatClock() {
  const totalMinutes = Math.floor(state.minute);
  const hour = Math.floor(totalMinutes / 60) % 24;
  const minute = totalMinutes % 60;
  const ampm = hour >= 12 ? 'PM' : 'AM';
  const twelve = hour % 12 || 12;
  return `${String(twelve).padStart(2, '0')}:${String(minute).padStart(2, '0')} ${ampm}`;
}

function toast(msg) {
  hud.toast.textContent = msg;
  hud.toast.classList.add('show');
  state.toastTimer = 2.2;
}

function updateHint() {
  const target = getNearestInteractable();
  if (!target) {
    hud.hint.innerHTML = '<b>E</b> interact &nbsp;·&nbsp; <b>1</b> seeds &nbsp; <b>2</b> water';
    return;
  }
  const { type } = target;
  if (type === 'plant') hud.hint.innerHTML = '<b>E</b> plant parsnips';
  else if (type === 'water') hud.hint.innerHTML = '<b>E</b> water crop';
  else if (type === 'harvest') hud.hint.innerHTML = '<b>E</b> harvest crop';
  else hud.hint.innerHTML = '<b>E</b> interact';
}

function showGoalProgress() {
  const stage = objectiveStages[state.objectiveIndex];
  if (!stage) return;
  let value = 0;
  if (stage.type === 'plant') value = state.planted;
  if (stage.type === 'water') value = plots.filter(p => p.seeded && p.watered).length;
  if (stage.type === 'harvest') value = state.harvested;
  if (stage.type === 'money') value = state.moneyEarned;
  const ratio = Math.min(value / stage.target, 1);
  hud.goalProgress.style.width = `${ratio * 100}%`;
  hud.goalCount.textContent = `${Math.min(value, stage.target)} / ${stage.target}`;
  hud.objective.innerHTML = `${stage.title}<span>${stage.desc}</span>`;

  if (state.objectiveIndex === 0 && state.planted >= 4) {
    state.objectiveIndex = 1;
    toast('Objective complete! Time to water the crops.');
  }
  if (state.objectiveIndex === 1 && plots.filter(p => p.seeded && p.watered).length >= 4) {
    state.objectiveIndex = 2;
    toast('Great work! Now harvest the parsnips.');
  }
  if (state.objectiveIndex === 2 && state.harvested >= 4) {
    state.objectiveIndex = 3;
    toast('Nice haul! You can earn a little gold.');
  }
  if (state.objectiveIndex === 3 && state.moneyEarned >= 80) {
    state.objectiveIndex = 3;
    toast('Farm goals complete — your little homestead shines!');
  }
}

function updateHud() {
  hud.day.textContent = formatDay();
  hud.clock.textContent = formatClock();
  hud.seedCount.textContent = String(state.totalSeeds);
  hud.goldCount.textContent = `◈ ${state.gold}g`;
  showGoalProgress();
}

function getReachablePlot(player) {
  for (const p of plots) {
    const dist = Math.hypot(player.x - (p.x + 0.5), player.y - (p.y + 0.5));
    if (dist < 1.1) return p;
  }
  return null;
}

function getNearestInteractable() {
  let best = null;
  for (const p of plots) {
    const dist = Math.min(
      Math.hypot(players[0].x - (p.x + 0.5), players[0].y - (p.y + 0.5)),
      Math.hypot(players[1].x - (p.x + 0.5), players[1].y - (p.y + 0.5))
    );
    if (dist < 1.18) {
      if (!p.seeded) best = { plot: p, type: 'plant' };
      else if (p.grow >= 1 && p.ready) best = { plot: p, type: 'harvest' };
      else best = { plot: p, type: 'water' };
      break;
    }
  }
  return best;
}

function performInteraction() {
  const target = getNearestInteractable();
  if (!target) {
    toast('Nothing nearby to interact with.');
    return;
  }
  const p = target.plot;
  if (target.type === 'plant') {
    if (state.totalSeeds <= 0) {
      toast('No more seeds left.');
      return;
    }
    if (p.seeded) {
      toast('This plot already has a crop.');
      return;
    }
    p.seeded = true;
    p.watered = false;
    p.grow = 0;
    p.ready = false;
    state.totalSeeds -= 1;
    state.planted += 1;
    toast('Parsnip planted!');
  } else if (target.type === 'water') {
    if (!p.seeded) {
      toast('Plant something first.');
      return;
    }
    if (p.ready) {
      toast('This crop is already ready—harvest it!');
      return;
    }
    p.watered = true;
    toast('Your crop is watered.');
  } else if (target.type === 'harvest') {
    if (!p.seeded || !p.ready) {
      toast('This crop is not ready yet.');
      return;
    }
    p.seeded = false;
    p.watered = false;
    p.grow = 0;
    p.ready = false;
