103: function useAction(action='interact'){
104:  const plot=nearestPlot();
105:  if(!plot){notify('Walk up to a garden bed first.');return}
106:  const next=plotAction(plot);
107:  if(action==='plant'&&next!=='plant'){notify('That plot is already planted.');return}
108:  if(action==='water'&&next!=='water'){notify(next==='plant'?'Plant a seed here first.':'This parsnip is ready to pick!');return}
109:  if(action==='interact')action=next;
110:  if(action==='plant'){
111:   if(seed<=0){notify('You are out of seeds.');return}
112:   plot.seeded=true;plot.watered=false;plot.grow=0;seed--;planted++;notify('Parsnip planted! Water it to help it grow.');
113:  }else if(action==='water'){
114:   if(!plot.seeded){notify('Plant a seed here first.');return}
115:   if(plot.ready){notify('Your parsnip is ready to harvest!');return}
116:   if(plot.watered){notify('This crop is already watered.');return}
117:   plot.watered=true;notify('Splash! The parsnip is watered.');
118:  }else if(action==='harvest'){
